   import jwt from 'jsonwebtoken';
   import { config } from '../config';

   interface AccessTokenPayload {
     sub: string;      // userId
     org: string;      // organizationId
     role: UserRole;
     sv: number;       // session version
     type: 'access';
   }

   interface RefreshTokenPayload {
     sub: string;
     fam: string;      // family ID for reuse detection
     type: 'refresh';
   }

   export const signAccessToken = (payload: Omit<AccessTokenPayload, 'type'>): string => {
     return jwt.sign({ ...payload, type: 'access' }, config.jwt.secret, {
       algorithm: 'HS256',
       expiresIn: '1h',
     });
   };

   export const signRefreshToken = (payload: Omit<RefreshTokenPayload, 'type'>): string => {
     return jwt.sign({ ...payload, type: 'refresh' }, config.jwt.secret, {
       algorithm: 'HS256',
       expiresIn: '7d',
     });
   };

   export const verifyToken = <T>(token: string): T => {
     return jwt.verify(token, config.jwt.secret, {
       algorithms: ['HS256'],  // CRITICAL: pin algorithm
     }) as T;
   };
   ```
3. CRITICAL: Always specify algorithms array in jwt.verify to prevent algorithm confusion attacks.
