   export const enqueueAudit = async (ctx: RequestContext, event: AuditEvent): Promise<void> => {
     // Fire and forget - errors logged but not thrown
     try {
       await prisma.outboxEvent.create({
         data: {
           event_type: 'audit.write',
           payload: {
             ...event,
             organization_id: ctx.orgId,
             user_id: ctx.userId,
             ip_address: ctx.ip,
             user_agent: ctx.userAgent,
             request_id: ctx.requestId,
             timestamp: new Date().toISOString(),
           },
         },
       });
     } catch (err) {
       ctx.log.error({ err, event: event.event }, 'Failed to enqueue audit event');
     }
   };
   ```
