   const ALLOWED_TYPES = [
     { mime: 'image/jpeg', magic: [0xFF, 0xD8, 0xFF] },
     { mime: 'image/png', magic: [0x89, 0x50, 0x4E, 0x47] },
     { mime: 'image/webp', magic: [0x52, 0x49, 0x46, 0x46] },
   ];
   const MAX_SIZE = 2 * 1024 * 1024; // 2 MiB

   async upload(incidentId: string, file: Express.Multer.File, userId: string) {
     // 1. Verify magic bytes
     const detectedType = await fileTypeFromBuffer(file.buffer);
     if (!ALLOWED_TYPES.some(t => t.mime === detectedType?.mime)) {
       throw new ValidationError('INVALID_FILE_TYPE');
     }

     // 2. Re-encode with sharp (strips EXIF/GPS)
     const processed = await sharp(file.buffer)
       .rotate() // auto-rotate based on EXIF before stripping
       .toFormat(detectedType.ext as 'jpeg' | 'png' | 'webp')
       .toBuffer();

     // 3. Encrypt
     const { ciphertext, iv, tag } = encrypt(processed.toString('base64'), encryptionKey);

     // 4. Store with UUID filename
     const fileKey = `${incidentId}/${crypto.randomUUID()}.enc`;
     await fs.writeFile(path.join(UPLOAD_DIR, fileKey), ciphertext);

     // 5. Save metadata
     return repo.create({ incident_id: incidentId, file_key: fileKey, encryption_iv: iv, ... });
   }
